From d1262a39685ab4b70725674e1872cc5660eb0f57 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:34:20 +0100
Subject: [PATCH] applets/showActivityManager: highlight while the switcher is
 open

The Activities button gave no feedback while its sidebar was open. The
desktop now tells the switcher backend when the sidebar is shown, and
the applet then draws the same active indicator as other panel widgets.

BUG: 466404
---
 applets/showActivityManager/qml/main.qml    | 55 +++++++++++++++++++++
 desktoppackage/contents/views/Desktop.qml   |  1 +
 imports/activitymanager/switcherbackend.cpp | 15 ++++++
 imports/activitymanager/switcherbackend.h   |  6 +++
 4 files changed, 77 insertions(+)

diff --git a/applets/showActivityManager/qml/main.qml b/applets/showActivityManager/qml/main.qml
index efb76fe880..17c36ba5d1 100644
--- a/applets/showActivityManager/qml/main.qml
+++ b/applets/showActivityManager/qml/main.qml
@@ -14,6 +14,7 @@ import org.kde.draganddrop as DND

 import org.kde.plasma.activityswitcher as ActivitySwitcher
 import org.kde.kirigami as Kirigami
+import org.kde.ksvg as KSvg
 import org.kde.activities as Activities

 import org.kde.kcmutils as KCM
@@ -112,6 +113,60 @@ PlasmoidItem {
             text: currentActivity.name
             textFormat: Text.PlainText
         }
+
+        KSvg.FrameSvgItem {
+            property var containerMargins: {
+                let item = this;
+                while (item.parent) {
+                    item = item.parent;
+                    if (item.isAppletContainer) {
+                        return item.getMargins;
+                    }
+                }
+                return undefined;
+            }
+
+            anchors {
+                fill: parent
+                property bool returnAllMargins: true
+                // The above makes sure margin is returned even for side margins
+                // that would be otherwise turned off.
+                topMargin: !root.inVertical && containerMargins ? -containerMargins('top', returnAllMargins) : 0
+                leftMargin: root.inVertical && containerMargins ? -containerMargins('left', returnAllMargins) : 0
+                rightMargin: root.inVertical && containerMargins ? -containerMargins('right', returnAllMargins) : 0
+                bottomMargin: !root.inVertical && containerMargins ? -containerMargins('bottom', returnAllMargins) : 0
+            }
+            imagePath: "widgets/tabbar"
+            visible: opacity > 0
+            prefix: {
+                let prefix;
+                switch (Plasmoid.location) {
+                case PlasmaCore.Types.LeftEdge:
+                    prefix = "west-active-tab";
+                    break;
+                case PlasmaCore.Types.TopEdge:
+                    prefix = "north-active-tab";
+                    break;
+                case PlasmaCore.Types.RightEdge:
+                    prefix = "east-active-tab";
+                    break;
+                default:
+                    prefix = "south-active-tab";
+                }
+                if (!hasElementPrefix(prefix)) {
+                    prefix = "active-tab";
+                }
+                return prefix;
+            }
+            opacity: ActivitySwitcher.Backend.activityManagerOpen ? 1 : 0
+
+            Behavior on opacity {
+                NumberAnimation {
+                    duration: Kirigami.Units.shortDuration
+                    easing.type: Easing.InOutQuad
+                }
+            }
+        }
     }

     Plasmoid.contextualActions: [
diff --git a/desktoppackage/contents/views/Desktop.qml b/desktoppackage/contents/views/Desktop.qml
index 1be09364ef..7ccb112df7 100644
--- a/desktoppackage/contents/views/Desktop.qml
+++ b/desktoppackage/contents/views/Desktop.qml
@@ -287,6 +287,7 @@ Item {
                 sidePanel.visible = true;
             }
             onStateChanged: {
+                ActivitySwitcher.Backend.activityManagerOpen = state === "activityManager";
                 if (state === "closed") {
                     sidePanel.visible = false;
                     source = ""; //unload all elements
diff --git a/imports/activitymanager/switcherbackend.cpp b/imports/activitymanager/switcherbackend.cpp
index 3744bc1fe2..a6c2500b08 100644
--- a/imports/activitymanager/switcherbackend.cpp
+++ b/imports/activitymanager/switcherbackend.cpp
@@ -341,6 +341,21 @@ void SwitcherBackend::setShouldShowSwitcher(bool shouldShowSwitcher)
     Q_EMIT shouldShowSwitcherChanged(m_shouldShowSwitcher);
 }

+bool SwitcherBackend::activityManagerOpen() const
+{
+    return m_activityManagerOpen;
+}
+
+void SwitcherBackend::setActivityManagerOpen(bool open)
+{
+    if (m_activityManagerOpen == open) {
+        return;
+    }
+
+    m_activityManagerOpen = open;
+    Q_EMIT activityManagerOpenChanged();
+}
+
 QAbstractItemModel *SwitcherBackend::runningActivitiesModel() const
 {
     return m_runningActivitiesModel;
diff --git a/imports/activitymanager/switcherbackend.h b/imports/activitymanager/switcherbackend.h
index 76900de797..a1f9cd1379 100644
--- a/imports/activitymanager/switcherbackend.h
+++ b/imports/activitymanager/switcherbackend.h
@@ -44,6 +44,7 @@ class SwitcherBackend : public QObject

     Q_PROPERTY(bool shouldShowSwitcher READ shouldShowSwitcher WRITE setShouldShowSwitcher NOTIFY shouldShowSwitcherChanged)
     Q_PROPERTY(bool dropEnabled READ dropEnabled CONSTANT)
+    Q_PROPERTY(bool activityManagerOpen READ activityManagerOpen WRITE setActivityManagerOpen NOTIFY activityManagerOpenChanged)

 public:
     explicit SwitcherBackend(QObject *parent);
@@ -54,6 +55,7 @@ public:
 Q_SIGNALS:
     void showSwitchNotification(const QString &id, const QString &name, const QString &icon);
     void shouldShowSwitcherChanged(bool value);
+    void activityManagerOpenChanged();

 public Q_SLOTS:
     void init();
@@ -61,6 +63,9 @@ public Q_SLOTS:
     bool shouldShowSwitcher() const;
     void setShouldShowSwitcher(bool shouldShowSwitcher);

+    bool activityManagerOpen() const;
+    void setActivityManagerOpen(bool open);
+
     QAbstractItemModel *runningActivitiesModel() const;

     void setCurrentActivity(const QString &activity);
@@ -101,6 +106,7 @@ private:
     KModifierKeyInfo m_modifierInfo;
     KActivities::Controller m_activities;
     bool m_shouldShowSwitcher;
+    bool m_activityManagerOpen = false;
     QTimer m_modKeyPollingTimer;
     QString m_previousActivity;

